function Get-LatestAssBackup {
    if (-not (Test-Path -LiteralPath $backupRoot -PathType Container)) {
        throw "reass: backup root not found: $backupRoot"
    }

    $candidates = foreach ($directory in Get-ChildItem -LiteralPath $backupRoot -Directory -Force -ErrorAction Stop) {
        if ($directory.Name -like 'pre-restore_*' -or $directory.Name -like '*.partial-*') {
            continue
        }
        $auditPath = Join-Path $directory.FullName 'backup.json'
        if (-not (Test-Path -LiteralPath $auditPath -PathType Leaf)) {
            continue
        }

        try {
            $audit = Get-Content -LiteralPath $auditPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            $sources = @($audit.saveSources | Where-Object { $_ -is [string] -and $_.Length -gt 0 })
            if ($sources.Count -eq 0 -or -not $audit.detectedUtc) {
                continue
            }
            [pscustomobject]@{
                Directory   = $directory
                Audit       = $audit
                Sources     = $sources
                DetectedUtc = [DateTimeOffset]::Parse([string]$audit.detectedUtc)
            }
        }
        catch {
            continue
        }
    }

    $latest = @($candidates | Sort-Object DetectedUtc, @{ Expression = { $_.Directory.LastWriteTimeUtc } } -Descending | Select-Object -First 1)
    if ($latest.Count -ne 1) {
        throw "reass: no valid backup created by ass was found under $backupRoot"
    }
    $latest[0]
}

